const tests = [
  // T6: Авария модели
  /*
  {
    json: {
      label: 'T6_SBT — авария модели → 502',
      customer: 'SST_Fedor',
      contact: 'sbt_fedor@test.ru',
      text: 'Нужен фильтр масляный FLT-100 1 шт.',
      headers: {}
    }
  },
  */

  // T7: Выключатель
  /*
  {
    json: {
      label: 'T7_SBT — выключатель → 503',
      customer: 'SST_Test',
      contact: 'sbt_switch@test.ru',
      text: 'Тест выключателя SST',
      headers: {}
    }
  }
  */
];

// Временная проверка - удали после запуска
console.log('Количество тестов:', tests.length);
console.log('Первый тест:', JSON.stringify(tests[0], null, 2));

if (tests.length === 0) {
  throw new Error('⚠️ Нет активных тестов!');
}
return tests;

// ===== СВОДКА РЕЗУЛЬТАТОВ SBT (Защищенная версия) =====
const results = $input.all().map(item => {
  const data = item.json || {};

  // Безопасное извлечение меток
  const label = data.label || 'unknown_test';
  const statusCode = data.statusCode || (data.error && data.error.statusCode) || 'N/A';

  // Безопасная обработка тела ответа (строка/объект/undefined)
  let body = '';
  if (typeof data.body === 'string') {
    body = data.body.slice(0, 300);
  } else if (data.body && typeof data.body === 'object') {
    body = JSON.stringify(data.body).slice(0, 300);
  } else if (data.error && typeof data.error.message === 'string') {
    body = data.error.message.slice(0, 300);
  } else {
    body = 'No response body or error details available';
  }

  return { label, statusCode, body };
});

// Формирование итоговой сводки
const summary = results.length > 0 
  ? results.map(r => `${r.label} → ${r.statusCode}`).join('\n')
  : '⚠️ Нет активных тестов. Раскомментируйте строки T6/T7 в ноде "Генерация SBT" перед запуском.';

return [{ json: { 
  summary,
  results,
  timestamp: new Date().toISOString(),
  test_count: results.length
} }];
